package bo.com.ganadero.sanidad.api;import bo.com.ganadero.sanidad.application.CrearJornadaCommand;import bo.com.ganadero.sanidad.domain.TipoActividadSanitaria;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.util.UUID;
